 return results[:top_k] def multimodal_rag( self, query_image: str, query_text: str ) -&gt; str: &#34;&#34;&#34;多模态RAG问答&#34;&#34;&#34; # 检索相关内容 image_results = self.retrieve(query_image=query_image) text_results = self.retrieve(query_text=query_text) # 构建prompt context = &#34;Retrieved Information:
